data control;
	set ajca.loancompustat;
	tnw=at - lt - intan;
	ln_tnw = log(1 + tnw);
	cr = act / lct;
	dtnw = (dltt + dlc) / tnw;
	fcc = oibdp / (xint + dlc);
	z_score = (3.3 * (pi / at)) + (sale / at) + (1.4 * (re / at)) + (1.2 * ((act - lct) / at)) + (0.6 * ((prcc_f * csho) / lt));
	cash = che / at; 
	booklev = (dlc + dltt) / at;
	mtb = (at - (at - lt + txditc) + (prcc_f * csho)) / at;
run;
proc expand data = control out = control method = none;
	id fyear;
	by gvkey;
	convert ln_tnw = l1_ln_tnw / transformout = (lag 1);
	convert cr = l1_cr / transformout = (lag 1);
	convert dtnw = l1_dtnw / transformout = (lag 1);
	convert fcc = l1_fcc / transformout = (lag 1);
	convert z_score = l1_z_score / transformout = (lag 1);
run;
