	select a.*, B.tnw, B.ln_tnw, B.l1_ln_tnw, B.cr, B.l1_cr, B.dtnw, B.l1_dtnw, B.fcc, B.l1_fcc, B.z_score, /*
	*/ B.l1_z_score, B.cash, B.booklev, B.mtb
